246	// 未解除冻结没有解除日期和原因是合法状态，仍要继续阻止销毁；
247	// 已解除冻结的解除日期与冻结日期相同也合法，历史保留完整信息且不再阻碍。
248	func TestValidFreezeRecordsKeepWorking(t *testing.T) {
249		t.Run("未解除冻结合法且阻止销毁", func(t *testing.T) {
250			dir := t.TempDir()
251			s, err := Open(dir)
252			if err != nil {
253				t.Fatal(err)
254			}
255			defer s.Close()
256			reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
257			if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
258				t.Fatal(err)
259			}
260			r, err := s.Check(CheckRequest{
261				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
262			})
263			if err != nil {
264				t.Fatalf("未解除冻结是合法记录，核对不应报错: %v", err)
265			}
266			if r.Status != CheckBlocked || len(r.Results[0].Obstructions) != 1 ||
267				r.Results[0].Obstructions[0].Kind != ObstructionActiveFreeze {
268				t.Fatalf("未解除冻结应给出一条冻结阻碍: %+v", r)
269			}
270			if _, err := s.Destroy(DestructionRequest{
271				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
272			}); !errors.Is(err, ErrActiveFreeze) {
273				t.Fatalf("未解除冻结应阻止销毁，得到 %v", err)
274			}
275		})
276	
277		t.Run("解除日期与冻结日期相同合法", func(t *testing.T) {
278			dir := t.TempDir()
279			s, err := Open(dir)
280			if err != nil {
281				t.Fatal(err)
282			}
283			defer s.Close()
284			reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
285			if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
286				t.Fatal(err)
287			}
288			if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-05")}); err != nil {
289				t.Fatalf("解除日期与冻结日期相同应合法: %v", err)
290			}
291			h, found, err := s.History("A-1")
292			if err != nil || !found {
293				t.Fatalf("历史查询失败: found=%v err=%v", found, err)
294			}
295			if len(h.Freezes) != 1 || !h.Freezes[0].Released ||
296				h.Freezes[0].ReleaseReason != "结案" ||
297				!h.Freezes[0].ReleasedOn.Equal(MustParseDate("2025-01-05")) ||
298				len(h.ActiveFreezes) != 0 {
299				t.Fatalf("历史应保留完整解除信息且不再算作未解除: %+v", h.Freezes)
300			}
301			r, err := s.Check(CheckRequest{
302				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
303			})
304			if err != nil {
305				t.Fatalf("核对不应报错: %v", err)
306			}
307			if r.Status != CheckReady {
308				t.Fatalf("已解除冻结不应阻碍销毁: %+v", r)
309			}
310			if _, err := s.Destroy(DestructionRequest{
311				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
312			}); err != nil {
313				t.Fatalf("到期且无未解除冻结时应能销毁: %v", err)
314			}
315		})
316	}
317	
318	// rewriteState 解析已保存状态、按 fn 修改后原样写回（保持 JSON 合法），
319	// 用于模拟保管库打开之后保存内容被改成语义损坏的记录。
320	func rewriteState(t *testing.T, dir string, fn func(map[string]any)) {
321		t.Helper()
322		path := filepath.Join(dir, stateFileName)
323		raw, err := os.ReadFile(path)
324		if err != nil {
325			t.Fatal(err)
326		}
327		var doc map[string]any
328		if err := json.Unmarshal(raw, &doc); err != nil {
329			t.Fatal(err)
330		}
331		fn(doc)
332		out, err := json.MarshalIndent(doc, "", "  ")
333		if err != nil {
334			t.Fatal(err)
335		}
336		if err := os.WriteFile(path, out, 0o600); err != nil {
337			t.Fatal(err)
338		}
339	}
340	
341	// 保管库打开后保存内容才出现不完整解除记录：下一次使用有效输入的
342	// 历史查询、清册查询、销毁前核对与正式销毁都必须返回 ErrCorruptState，
343	// 不能把档案说成不存在、不能给出可以办理或部分报告、不能生成清册，
344	// 且失败后原保存内容保持原样。
345	func TestIncompleteReleaseAfterOpenFailsAllOperations(t *testing.T) {
346		dir := t.TempDir()
347		s, err := Open(dir)
348		if err != nil {
349			t.Fatal(err)
350		}
351		defer s.Close()
352		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
353		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
354			t.Fatal(err)
355		}
356		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-06")}); err != nil {
357			t.Fatal(err)
358		}
359		if _, found, err := s.History("A-1"); err != nil || !found {
360			t.Fatalf("损坏前查询应成功: found=%v err=%v", found, err)
361		}
362	
363		// 把解除原因改空：只剩“已解除”标记。
364		rewriteState(t, dir, func(doc map[string]any) {
365			freezes := doc["archives"].(map[string]any)["A-1"].(map[string]any)["freezes"].([]any)
366			freezes[0].(map[string]any)["release_reason"] = "   "
367		})
368		corruptContent := readStateFile(t, dir)
369	
370		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
371			t.Fatalf("损坏后 History 必须返回 ErrCorruptState 且无结论: found=%v err=%v", found, err)
372		}
373		if _, found, err := s.GetManifest("APP-1"); !errors.Is(err, ErrCorruptState) || found {
374			t.Fatalf("损坏后 GetManifest 必须返回 ErrCorruptState: found=%v err=%v", found, err)
375		}
376		if r, err := s.Check(CheckRequest{
377			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
378		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
379			t.Fatalf("损坏后 Check 必须失败且不得给出部分报告: %+v err=%v", r, err)
380		}
381		if m, err := s.Destroy(DestructionRequest{
382			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
383		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
384			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
385		}
386		if err := s.Register(RegisterInput{ID: "A-2", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-01-10")}); !errors.Is(err, ErrCorruptState) {
387			t.Fatalf("损坏后 Register 必须失败: %v", err)
388		}
389		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-2", Reason: "审计", FrozenOn: MustParseDate("2025-01-07")}); !errors.Is(err, ErrCorruptState) {
390			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
391		}
392	
393		// 失败不得触发重新保存：损坏内容原样保留，不补原因、不删冻结。
394		if got := readStateFile(t, dir); got != corruptContent {
395			t.Fatalf("失败后原保存内容被改动:\n%q", got)
396		}
397	}
398	
399	// 损坏判断适用于库内全部已解除冻结，与本次办理名单无关：
400	// 异常记录挂在另一份已经销毁的档案下时，查询、核对、销毁其他档案
401	// 同样必须按记录损坏失败，不能把不完整解除信息作为正常历史返回。
402	func TestCorruptReleaseOnDestroyedArchiveFailsWholeVault(t *testing.T) {
403		dir := t.TempDir()
404		s, err := Open(dir)
405		if err != nil {
406			t.Fatal(err)
407		}
408		defer s.Close()
409		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
410		reg(t, s, "D-1", "凭证", "2020-01-01", "2025-01-10")
411		if err := s.Freeze(FreezeInput{ArchiveID: "D-1", FreezeID: "F-D", Reason: "协查", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
412			t.Fatal(err)
413		}
414		if err := s.Release(ReleaseInput{ArchiveID: "D-1", FreezeID: "F-D", Reason: "协查结束", ReleasedOn: MustParseDate("2025-01-06")}); err != nil {
415			t.Fatal(err)
416		}
417		if _, err := s.Destroy(DestructionRequest{
418			ApplicationID: "APP-D", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"D-1"},
419		}); err != nil {
420			t.Fatal(err)
421		}
422	
423		// 损坏发生在已销毁档案 D-1 身上（去掉解除日期）。
424		rewriteState(t, dir, func(doc map[string]any) {
425			freezes := doc["archives"].(map[string]any)["D-1"].(map[string]any)["freezes"].([]any)
426			delete(freezes[0].(map[string]any), "released_on")
427		})
428		corruptContent := readStateFile(t, dir)
429	
430		// 重新打开整个位置必须失败，错误指出 D-1 与 F-D。
431		s2, err := Open(dir)
432		if err == nil {
433			s2.Close()
434			t.Fatal("库内任一已解除冻结不完整时，打开必须失败")
435		}
436		if !errors.Is(err, ErrCorruptState) || !strings.Contains(err.Error(), "D-1") || !strings.Contains(err.Error(), "F-D") {
437			t.Fatalf("打开错误应为 ErrCorruptState 并指出 D-1/F-D，得到 %v", err)
438		}
439	
440		// 已打开的实例：即使本次只查询、核对、销毁与异常记录无关的 A-1，
441		// 也必须按整库损坏失败。
442		if _, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found {
443			t.Fatalf("查询无关档案 A-1 也应返回 ErrCorruptState: found=%v err=%v", found, err)
444		}
445		if _, found, err := s.History("D-1"); !errors.Is(err, ErrCorruptState) || found {
446			t.Fatalf("查询已销毁的异常档案不得返回（不完整的）历史: found=%v err=%v", found, err)
447		}
448		if _, found, err := s.GetManifest("APP-D"); !errors.Is(err, ErrCorruptState) || found {
449			t.Fatalf("查询异常档案所属清册也应失败: found=%v err=%v", found, err)
450		}
451		if r, err := s.Check(CheckRequest{
452			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
453		}); !errors.Is(err, ErrCorruptState) || r.Status != "" {
454			t.Fatalf("核对无关档案也应整次失败: %+v err=%v", r, err)
455		}
456		if m, err := s.Destroy(DestructionRequest{
457			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
458		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
459			t.Fatalf("不得在损坏状态下生成清册: %+v err=%v", m, err)
460		}
461		if got := readStateFile(t, dir); got != corruptContent {
462			t.Fatalf("失败后原保存内容被改动:\n%q", got)
463		}
464	}
