1	package retention
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 同一档案的冻结历史中保存了两条相同编号的冻结时，即使其余内容全部合法，
10	// Open 也必须按保存记录损坏失败（ErrCorruptState）：错误指出档案编号与
11	// 重复的冻结编号，原文件保持原样。两条都未解除、一解一未解、两条均已解除
12	// （即使原因、日期和解除信息完全一致）结果相同，不能合并成一条。
13	// 已销毁档案（清册归属、期限与处理日期都正确、冻结全部合法解除）同样遵守。
14	func TestOpenRejectsDuplicateFreezeIDWithinArchive(t *testing.T) {
15		freezeActive := func(id string) string {
16			return `{"id":"` + id + `","reason":"诉讼","frozen_on":"2025-01-05","released":false}`
17		}
18		freezeReleased := func(id, reason, frozenOn, releasedOn string) string {
19			return `{"id":"` + id + `","reason":"` + reason + `","frozen_on":"` + frozenOn +
