140	// 保管库打开后保存内容才出现同一档案冻结编号重复：
141	// 下一次使用有效输入查询历史、取回清册（含已成功申请的幂等重放）、销毁前
142	// 核对与各项办理都必须按整库记录损坏失败——即使操作的是另一份正常档案——
143	// 解除申请不得挑一条同号记录写入原因和日期，销毁申请不得生成清册，
144	// 不返回正常历史、清册或部分核对报告，原保存内容保持原样。
145	func TestDuplicateFreezeIDAfterOpenFailsAllOperations(t *testing.T) {
146		dir := t.TempDir()
147		s, err := Open(dir)
148		if err != nil {
149			t.Fatal(err)
150		}
151		defer s.Close()
152		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
153		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
154		reg(t, s, "A-3", "单据", "2020-01-01", "2025-01-10")
155		if err := s.Freeze(FreezeInput{
156			ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05"),
157		}); err != nil {
158			t.Fatal(err)
159		}
160		if err := s.Freeze(FreezeInput{
161			ArchiveID: "A-1", FreezeID: "F-2", Reason: "审计", FrozenOn: MustParseDate("2025-01-07"),
162		}); err != nil {
163			t.Fatal(err)
164		}
165		// A-3 先合法销毁，供损坏后验证“取回清册”同样整库失败。
166		if _, err := s.Destroy(DestructionRequest{
167			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
168		}); err != nil {
169			t.Fatal(err)
170		}
171		if _, found, err := s.GetManifest("APP-3"); err != nil || !found {
172			t.Fatalf("损坏前清册应可取回: found=%v err=%v", found, err)
173		}
174	
175		// 把 A-1 的第二条冻结编号改成与第一条相同。
176		rewriteState(t, dir, func(doc map[string]any) {
177			freezes := doc["archives"].(map[string]any)["A-1"].(map[string]any)["freezes"].([]any)
178			freezes[1].(map[string]any)["id"] = "F-1"
179		})
180		corruptContent := readStateFile(t, dir)
181	
182		// 重新打开必须失败，错误指出档案与重复的冻结编号。
183		s2, err := Open(dir)
184		if err == nil {
185			s2.Close()
186			t.Fatal("冻结历史出现同号记录时，打开必须失败")
187		}
188		if !errors.Is(err, ErrCorruptState) ||
189			!strings.Contains(err.Error(), "A-1") ||
190			!strings.Contains(err.Error(), "F-1") {
191			t.Fatalf("打开错误应为 ErrCorruptState 并指出 A-1/F-1，得到 %v", err)
192		}
193	
194		// 已打开实例：即使本次只操作与重复记录无关的正常档案 A-2，
195		// 也必须按整库损坏失败。
196		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
197			t.Fatalf("损坏后查询无关档案也必须失败且无结论: found=%v err=%v", found, err)
198		}
199		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
200			t.Fatalf("损坏后 History 必须失败且不得给出正常冻结历史: found=%v err=%v", found, err)
201		}
202		if m, found, err := s.GetManifest("APP-3"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
203			t.Fatalf("损坏后 GetManifest 必须失败: found=%v err=%v %+v", found, err, m)
204		}
205		if r, err := s.Check(CheckRequest{
206			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
207		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
208			t.Fatalf("损坏后 Check 必须失败且不得给出可以办理等结论或部分报告: %+v err=%v", r, err)
209		}
210		if m, err := s.Destroy(DestructionRequest{
211			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
212		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
213			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
214		}
215		// 已成功申请的幂等重放同样不能取回原清册。
216		if m, err := s.Destroy(DestructionRequest{
217			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
218		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
219			t.Fatalf("损坏后已成功申请的重放也必须失败且不得返回原清册: %+v err=%v", m, err)
220		}
221		if err := s.Register(RegisterInput{
222			ID: "A-4", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-06-30"),
223		}); !errors.Is(err, ErrCorruptState) {
224			t.Fatalf("损坏后 Register 必须失败: %v", err)
225		}
226		if err := s.Freeze(FreezeInput{
227			ArchiveID: "A-2", FreezeID: "F-X", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01"),
228		}); !errors.Is(err, ErrCorruptState) {
229			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
230		}
231		// 解除申请不得在两条同号记录中挑一条写入原因和日期。
232		if err := s.Release(ReleaseInput{
233			ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
234		}); !errors.Is(err, ErrCorruptState) {
