237		if _, err := s.Revise(ReviseInput{
238			RevisionID: "R-9", ArchiveID: "A-2",
239			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
240			RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
241		}); !errors.Is(err, ErrCorruptState) {
242			t.Fatalf("损坏后 Revise 必须失败: %v", err)
243		}
244	
245		// 失败不得触发修复：不改冻结编号，不删除、合并或自动解除重复记录。
246		if got := readStateFile(t, dir); got != corruptContent {
247			t.Fatalf("失败后原保存内容被改动:\n%q", got)
248		}
249	
250		// 恢复唯一编号后，合法记录恢复可用：解除只作用于唯一一条 F-1，
251		// A-1 的 F-2 仍是未解除阻碍，无关档案业务不受影响。
252		rewriteState(t, dir, func(doc map[string]any) {
253			freezes := doc["archives"].(map[string]any)["A-1"].(map[string]any)["freezes"].([]any)
254			freezes[1].(map[string]any)["id"] = "F-2"
255		})
256		if err := s.Release(ReleaseInput{
257			ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
258		}); err != nil {
