262		if err != nil || !found || len(h.Freezes) != 2 {
263			t.Fatalf("恢复后完整历史应保留两条冻结: found=%v err=%v %+v", found, err, h)
264		}
265		if !h.Freezes[0].Released || h.Freezes[0].ReleaseReason != "结案" ||
266			h.Freezes[1].Released || h.Freezes[1].ID != "F-2" {
267			t.Fatalf("解除应只作用于 F-1，F-2 保持未解除: %+v", h.Freezes)
268		}
269		if r, err := s.Check(CheckRequest{
270			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
271		}); err != nil || r.Status != CheckBlocked {
272			t.Fatalf("恢复后 F-2 仍应逐条作为销毁阻碍: %+v err=%v", r, err)
273		}
274		if _, err := s.Destroy(DestructionRequest{
275			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
276		}); err != nil {
277			t.Fatalf("恢复后无关档案应能正常办理销毁: %v", err)
278		}
279	}
280	
281	// 唯一性只限定在同一份档案内：不同档案各有一条同编号冻结是合法情况，
282	// 解除其中一份档案的冻结不能影响另一份；同一档案多条不同编号冻结的完整历史
283	// 按登记顺序返回，未解除记录逐条作为销毁阻碍，全部合法解除后才按既有到期
284	// 规则办理销毁。重开后行为不变。
285	func TestFreezeIDUniquenessIsScopedPerArchive(t *testing.T) {
286		dir := t.TempDir()
287		s, err := Open(dir)
288		if err != nil {
289			t.Fatal(err)
290		}
291		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
292		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-01-10")
293		for _, archiveID := range []string{"A-1", "A-2"} {
294			if err := s.Freeze(FreezeInput{
295				ArchiveID: archiveID, FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05"),
296			}); err != nil {
297				t.Fatalf("不同档案使用相同冻结编号应合法: %v", err)
298			}
299		}
300		if err := s.Freeze(FreezeInput{
301			ArchiveID: "A-1", FreezeID: "F-2", Reason: "审计", FrozenOn: MustParseDate("2025-01-06"),
302		}); err != nil {
303			t.Fatal(err)
304		}
305	
306		// 只解除 A-1 的 F-1：A-2 的同编号冻结必须保持未解除。
307		if err := s.Release(ReleaseInput{
308			ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-07"),
309		}); err != nil {
310			t.Fatal(err)
311		}
312		h1, found, err := s.History("A-1")
313		if err != nil || !found {
314			t.Fatalf("查询 A-1 失败: found=%v err=%v", found, err)
315		}
316		if len(h1.Freezes) != 2 || !h1.Freezes[0].Released || h1.Freezes[0].ID != "F-1" ||
317			h1.Freezes[1].ID != "F-2" || h1.Freezes[1].Released {
318			t.Fatalf("A-1 历史应按登记顺序保留两条且只解除 F-1: %+v", h1.Freezes)
319		}
320		if len(h1.ActiveFreezes) != 1 || h1.ActiveFreezes[0].ID != "F-2" {
321			t.Fatalf("A-1 应只剩 F-2 未解除: %+v", h1.ActiveFreezes)
322		}
323		h2, found, err := s.History("A-2")
324		if err != nil || !found {
325			t.Fatalf("查询 A-2 失败: found=%v err=%v", found, err)
326		}
327		if len(h2.Freezes) != 1 || h2.Freezes[0].ID != "F-1" || h2.Freezes[0].Released {
328			t.Fatalf("A-2 的同编号冻结不应受 A-1 解除影响: %+v", h2.Freezes)
329		}
330	
331		// A-2 仍被其 F-1 阻挡；A-1 仍被 F-2 阻挡，核对时逐条列出。
332		r, err := s.Check(CheckRequest{
333			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"),
334			ArchiveIDs: []string{"A-1", "A-2"},
335		})
336		if err != nil || r.Status != CheckBlocked {
337			t.Fatalf("两份档案都应存在未解除冻结阻碍: %+v err=%v", r, err)
338		}
339		if len(r.Results) != 2 ||
340			len(r.Results[0].Obstructions) != 1 || r.Results[0].Obstructions[0].Freeze.FreezeID != "F-2" ||
341			len(r.Results[1].Obstructions) != 1 || r.Results[1].Obstructions[0].Freeze.FreezeID != "F-1" {
342			t.Fatalf("阻碍应逐条对应各自档案的未解除冻结: %+v", r.Results)
343		}
344	
345		// 重开后跨档案同编号仍合法，隔离关系保持不变。
346		if err := s.Close(); err != nil {
347			t.Fatal(err)
348		}
349		s2, err := Open(dir)
350		if err != nil {
351			t.Fatalf("含跨档案同编号冻结的记录应能重新打开: %v", err)
352		}
353		defer s2.Close()
354		h2b, found, err := s2.History("A-2")
355		if err != nil || !found || len(h2b.ActiveFreezes) != 1 || h2b.ActiveFreezes[0].ID != "F-1" {
356			t.Fatalf("重开后 A-2 的 F-1 应仍未解除: found=%v err=%v %+v", found, err, h2b.ActiveFreezes)
357		}
358	
359		// 两份档案的冻结全部合法解除后，才按既有到期规则办理销毁。
360		if err := s2.Release(ReleaseInput{
361			ArchiveID: "A-1", FreezeID: "F-2", Reason: "审计结束", ReleasedOn: MustParseDate("2025-01-08"),
362		}); err != nil {
363			t.Fatal(err)
364		}
365		if err := s2.Release(ReleaseInput{
366			ArchiveID: "A-2", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
367		}); err != nil {
368			t.Fatal(err)
369		}
370		if _, err := s2.Destroy(DestructionRequest{
371			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"),
372			ArchiveIDs: []string{"A-1", "A-2"},
373		}); err != nil {
374			t.Fatalf("全部合法解除且到期后应能销毁: %v", err)
375		}
376	}
