	}
	entry := func(key, bodyText string) string {
		return `"` + key + `":{"` + bodyText + `}`
	}
	// rawKey 允许直接写入带转义的键；value 为完整的登记对象文本。
	entryRaw := func(rawKey, value string) string {
		return `"` + rawKey + `":` + value
	}
	state := func(archivesJSON string) string {
